use crate::txn::month_of;

/// The months a median may be taken over: WHOLE ones only, dropping a partial at either end.
pub(crate) fn whole_months(dates: &[String]) -> Vec<String> {
    let mut months: Vec<String> = dates.iter().map(|d| month_of(d).to_string()).collect();
    months.sort();
    months.dedup();
    if months.len() > 2 { months[1..months.len() - 1].to_vec() } else { months }
}
